def shape(g):
    from collections import Counter
    c=Counter(v for r in g for v in r); bg=c.most_common(1)[0][0]
    cells=[(i,j,v) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg]
    return bg,cells
