def extend_diagonals(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    for d in (1,-1):  # main diag (dr=1,dc=1) vs anti (dr=1,dc=-1)
        # group cells by line id
        from collections import defaultdict
        lines=defaultdict(list)
        for i in range(H):
            for j in range(W):
                if g[i][j]!=bg:
                    lines[j-d*i if d==1 else i+j].append((i,j,g[i][j]))
        for key,cells in lines.items():
            if len(cells)<2: continue
            col=cells[0][2]
            # walk both directions from each cell
            for i,j,_ in cells:
                for si,sj in ((d,d) if d==1 else (1,-1),(-d,-d) if d==1 else (-1,1)):
                    i2,j2=i+si,j+sj
                    while 0<=i2<H and 0<=j2<W and out[i2][j2]==bg:
                        out[i2][j2]=col; i2+=si; j2+=sj
    return out
